//! 非負被覆乗数の射影劣勾配を調べる独立下界診断。
use mip_codex::{mps,heuristic::Repair,objective_bound::Certifier,row_packing};
use std::{fs::File,time::{Instant,Duration}};
fn main(){let a:Vec<_>=std::env::args().collect();let m=mps::read(&a[1]).unwrap();assert!(!m.maximize&&m.variables.iter().all(|v|v.lower==Some(0.)&&v.upper==Some(1.)&&v.objective==1.));let input:serde_json::Value=serde_json::from_reader(File::open(&a[2]).unwrap()).unwrap();let incumbent:Vec<_>=m.variables.iter().map(|v|input["values"][&v.name].as_f64().unwrap()).collect();let start=Instant::now();let seconds:f64=a[3].parse().unwrap();let end=start+Duration::from_secs_f64(seconds);assert!(Repair::new(&m).candidate_check(&incumbent));let ub=m.objective(&incumbent);let factor:f64=a.get(4).map(|s|s.parse().unwrap()).unwrap_or(1.);let rows:Vec<_>=m.rows.iter().enumerate().filter(|(_,r)|r.exact_integral&&r.lower.is_some_and(|v|v>0.)&&r.coefficients.iter().all(|&(_,v)|v>=0.)).map(|(i,_)|i).collect();let mut y=vec![0.;m.rows.len()];if let Some(p)=row_packing::compute(&m,end.min(Instant::now()+Duration::from_millis(100))){for i in p.rows{y[i]=1.;}}let mut best=f64::NEG_INFINITY;let mut besty=y.clone();let mut iterations=0;let mut r=vec![1.;m.variables.len()];let mut x=vec![0.;r.len()];let mut gradient=vec![0.;rows.len()];
while Instant::now()<end&&iterations<10000{r.fill(1.);let mut value=m.offset;for &i in &rows{value+=y[i]*m.rows[i].lower.unwrap();for &(j,c)in &m.rows[i].coefficients{r[j]-=y[i]*c;}}for j in 0..r.len(){value+=r[j].min(0.);x[j]=if r[j]< -1e-9{1.}else if r[j]>1e-9{0.}else{incumbent[j]};}if value>best{best=value;besty.clone_from(&y);}let mut norm=0.;for(k,&i)in rows.iter().enumerate(){let g=m.rows[i].lower.unwrap()-m.rows[i].coefficients.iter().map(|&(j,c)|c*x[j]).sum::<f64>();gradient[k]=g;norm+=g*g;}if norm==0.{break;}let step=factor*(ub-value).max(0.)/(norm*((iterations+1)as f64).sqrt());for(k,&i)in rows.iter().enumerate(){y[i]=(y[i]+step*gradient[k]).max(0.);}iterations+=1;}
let lower:Vec<_>=m.variables.iter().map(|v|v.lower).collect();let upper:Vec<_>=m.variables.iter().map(|v|v.upper).collect();let bound=Certifier::new(&m).and_then(|c|c.bound(&lower,&upper,&besty)).map(f64::next_down);println!("{}",serde_json::json!({"iterations":iterations,"approximate_bound":best,"certified_bound":bound,"seconds":start.elapsed().as_secs_f64(),"multipliers":besty.iter().enumerate().filter(|(_,v)|**v!=0.).map(|(i,v)|serde_json::json!([i,format!("{:016x}",v.to_bits())])).collect::<Vec<_>>()}));}
